ee:message.ee:set-payload:
%dw 2.0
output application/json
var grounded = not (lower(payload.response as String) contains "i do not know")
---
{
  question: vars.question,
  answer: payload.response,
  grounded: grounded,
  source: if (grounded) vars.sources[0].fileName else null,
  retrievedChunks: vars.sources map {
    source: $.fileName,
    score: $.individualScore,
    text: $.textSegment
  }
}

%dw 2.0
output application/json
---
{
  question: vars.question,
  retrievedChunks: payload.sources map {
    source: $.fileName,
    score: $.individualScore,
    text: $.textSegment
  }
}
